const $=id=>document.getElementById(id);let status,brief,busy=false;
const workspace=new URL(location.href).searchParams.get('workspace');if(workspace)sessionStorage.setItem('notion-return-workspace',workspace);
const back=new URL('index.html',location.href),returnWorkspace=sessionStorage.getItem('notion-return-workspace');if(returnWorkspace)back.searchParams.set('workspace',returnWorkspace);$('back').href=back.href;
function controls(){ $('connect').disabled=busy||!status?.configured;$('disconnect').disabled=busy||!status?.connected;$('import').disabled=busy||!status?.connected; }
async function api(action,data){const response=await fetch('/api/notion/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-Lesson-CSRF':status.csrf},body:JSON.stringify(data||{})});const result=await response.json();if(!response.ok)throw Error(result.error||'The connection action failed.');return result;}
async function refresh(){try{const response=await fetch('/api/notion/status');if(!response.ok)throw Error('Open this page through the local Lesson Studio server.');status=await response.json();$('setup').hidden=status.configured;$('redirect').textContent=status.redirectUri;$('connection-status').textContent=status.connected?'Connected to '+status.workspace:status.configured?'Ready to sign in to Notion.':'Notion app registration is not configured.';if(new URL(location.href).searchParams.has('connection'))$('connection-status').textContent+=' The last sign-in did not finish. Try again when ready.';}catch(error){$('connection-status').textContent=error.message;}controls();}
async function run(operation){if(busy)return;busy=true;controls();try{await operation();}catch(error){$('import-status').textContent=error.message;}finally{busy=false;controls();}}
$('connect').onclick=()=>run(async()=>{const result=await api('start');location.href=result.url;});
$('disconnect').onclick=()=>run(async()=>{await api('disconnect');brief=null;$('use').hidden=true;$('download-brief').hidden=true;$('import-status').textContent='Disconnected locally. Existing draft content is unchanged.';await refresh();});
$('import').onclick=()=>run(async()=>{brief=null;$('use').hidden=true;$('download-brief').hidden=true;$('import-status').textContent='Reading the complete brief…';const result=await api('import',{page:$('page').value});brief=result;$('import-status').textContent=`Ready to review: ${brief.title||'Lesson brief'}; ${Object.keys(brief.fields).length} fields. ${brief.warnings.join(' ')}`;$('use').hidden=false;$('download-brief').hidden=false;});
$('use').onclick=()=>{try{if(!brief)return;const id=crypto.randomUUID();localStorage.setItem('lesson-studio-pending-source-'+id,JSON.stringify(brief));back.searchParams.set('sourceImport',id);location.href=back.href;}catch{$('import-status').textContent='Browser storage is unavailable. Your draft is unchanged. Free space before importing.';}};
await refresh();

$('download-brief').onclick=()=>{if(!brief)return;const url=URL.createObjectURL(new Blob([JSON.stringify({kind:'lesson-studio-brief',schemaVersion:1,brief},null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='notion-lesson-brief.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
